function cotPrompt(task, steps, style, lang){
  task=(task||'').trim(); if(!task) return {error:'请描述任务'};
  steps=Math.max(1,Math.min(10,(+steps)||3));
  style=(style||'zeroshot').toLowerCase();
  var L=(lang||'zh').toLowerCase()==='en';
  var head = L? 'Task: '+task : '任务：'+task;
  var stepLines=[];
  for(var i=1;i<=steps;i++){ stepLines.push((L?'Step '+i+': ':'第 '+i+' 步：')+'<'+ (L?'reasoning':'推理') +'>'); }
  var tail;
  if(style==='fewshot'){
    tail = L? '\nExample:\nQ: ...\nA: Let us think step by step. ...\n\nNow apply the same reasoning to the task above.'
            : '\n示例：\n问：…\n答：我们一步步思考。…\n\n请对上面的任务套用同样的推理。';
  } else if(style==='selfconsistency'){
    tail = L? '\nSolve the task in '+steps+' different step-by-step ways, then pick the most consistent answer.'
            : '\n用 '+steps+' 种不同的逐步推理各解一遍，再取最一致的结论。';
  } else {
    tail = L? '\nThink step by step, then give the final answer.'
            : '\n请一步步思考，再给出最终答案。';
  }
  var prompt = head+'\n'+stepLines.join('\n')+'\n'+tail;
  return {prompt:prompt, style:style, steps:steps};
}
var EXPORTS={cotPrompt:cotPrompt};

if (typeof module !== 'undefined' && module.exports) { module.exports = EXPORTS; }
if (typeof window !== 'undefined') { window.ChainOfThoughtForgePure = EXPORTS; }
